cs3Model = (function(b, e) local st, it = b.skillsTab, b.itemsTab local ws = { } for k, s in pairs(it.slots) do if s.weaponSet then ws[k] = s.weaponSet end end local socks = { } for slot, item in pairs(e.player.itemList) do socks[slot] = item.sockets end return { socketGroupList = st.socketGroupList, mainSocketGroup = b.mainSocketGroup, weaponSets = ws, useSecondWeaponSet = it.activeItemSet.useSecondWeaponSet or false, imbuedSupportBySlot = st.imbuedSupportBySlot, displayGroup = st.displayGroup, itemSockets = socks, characterLevel = b.characterLevel, spectreList = b.spectreList } end)(build, env),
